import { useEffect, useState } from "react"
import { ParticleLodestar } from "./lodestar-particles"

import "./hero-lodestar.css"

type Locale = "en" | "es"

type HeroCopy = {
  eyebrow: string
  titleLineOne: string
  titleLineTwo: string
  titleLineThree: string
  description: string
  primary: string
  secondary: string
  menu: string[]
}

const COPY: Record<Locale, HeroCopy> = {
  en: {
    eyebrow: "Creative technologist & digital designer",
    titleLineOne: "I craft web",
    titleLineTwo: "moments that",
    titleLineThree: "linger.",
    description:
      "I bring design and code together to shape tactile 3D stories, expressive interfaces, and motion-rich experiences — built with intention, down to the smallest detail.",
    primary: "Start a project",
    secondary: "Explore work",
    menu: ["Home", "Profile", "Selected work", "Contact"],
  },
  es: {
    eyebrow: "Tecnología creativa y diseño digital",
    titleLineOne: "Creo mundos",
    titleLineTwo: "digitales que",
    titleLineThree: "perduran.",
    description:
      "Uno diseño y código para crear historias 3D, interfaces expresivas y experiencias web construidas con intención.",
    primary: "Iniciar proyecto",
    secondary: "Ver trabajos",
    menu: ["Inicio", "Perfil", "Proyectos", "Contacto"],
  },
}

export type HeroLodestarProps = {
  className?: string
  brand?: string
  primaryHref?: string
  secondaryHref?: string
}


function FrameCorners() {
  return (
    <div className="hero-lodestar__frame" aria-hidden="true">
      <i className="hero-lodestar__corner hero-lodestar__corner--tl" />
      <i className="hero-lodestar__corner hero-lodestar__corner--tr" />
      <i className="hero-lodestar__corner hero-lodestar__corner--bl" />
      <i className="hero-lodestar__corner hero-lodestar__corner--br" />
    </div>
  )
}

export function HeroLodestar({
  brand = "Aster / Studio",
  className = "",
  primaryHref = "#contact",
  secondaryHref = "#work",
}: HeroLodestarProps) {
  const [locale, setLocale] = useState<Locale>("en")
  const [menuOpen, setMenuOpen] = useState(false)
  const [showIntro, setShowIntro] = useState(true)
  const copy = COPY[locale]

  useEffect(() => {
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    const timeout = window.setTimeout(() => setShowIntro(false), reducedMotion ? 80 : 1760)
    return () => window.clearTimeout(timeout)
  }, [])

  return (
    <section
      className={`hero-lodestar ${className}`}
      aria-labelledby="hero-lodestar-title"
    >
      <div className="hero-lodestar__aurora" aria-hidden="true" />
      <ParticleLodestar />
      <FrameCorners />

      <header className="hero-lodestar__header">
        <a className="hero-lodestar__brand" href="#home">
          {brand}
        </a>

        <div className="hero-lodestar__header-actions">
          <div className="hero-lodestar__locales" aria-label="Language">
            <button
              type="button"
              className={locale === "en" ? "is-active" : ""}
              onClick={() => setLocale("en")}
            >
              EN
            </button>
            <span aria-hidden="true">/</span>
            <button
              type="button"
              className={locale === "es" ? "is-active" : ""}
              onClick={() => setLocale("es")}
            >
              ES
            </button>
          </div>
          <button
            type="button"
            className={`hero-lodestar__menu-toggle ${menuOpen ? "is-open" : ""}`}
            aria-expanded={menuOpen}
            aria-controls="hero-lodestar-menu"
            aria-label={menuOpen ? "Close navigation menu" : "Open navigation menu"}
            onClick={() => setMenuOpen((open) => !open)}
          >
            <span />
            <span />
          </button>
        </div>
      </header>

      <nav
        id="hero-lodestar-menu"
        className={`hero-lodestar__menu ${menuOpen ? "is-open" : ""}`}
        aria-label="Primary navigation"
      >
        {copy.menu.map((item, index) => (
          <a
            href={`#${index === 0 ? "home" : index === 1 ? "profile" : index === 2 ? "work" : "contact"}`}
            key={item}
            onClick={() => setMenuOpen(false)}
          >
            {item}
          </a>
        ))}
      </nav>

      <div className="hero-lodestar__intro-copy">
        <p className="hero-lodestar__eyebrow">{copy.eyebrow}</p>
        <h1 id="hero-lodestar-title">
          <span className="hero-lodestar__title-line hero-lodestar__title-line--bright">
            {copy.titleLineOne}
          </span>
          <span className="hero-lodestar__title-line">{copy.titleLineTwo}</span>
          <span className="hero-lodestar__title-line">{copy.titleLineThree}</span>
        </h1>
      </div>

      <div className="hero-lodestar__actions">
        <a href={primaryHref}>{copy.primary}</a>
        <a href={secondaryHref}>{copy.secondary}</a>
      </div>

      <p className="hero-lodestar__description">{copy.description}</p>

      <div className="hero-lodestar__cursor" aria-hidden="true">
        <span />
      </div>

      {showIntro ? (
        <div className="hero-lodestar__loader" aria-hidden="true">
          <p>Where form meets motion.</p>
        </div>
      ) : null}
    </section>
  )
}

export default HeroLodestar

@import url("https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Red+Hat+Display:wght@400;500&display=swap");

.hero-lodestar {
  --lodestar-ink: #f5f4f8;
  --lodestar-muted: rgba(245, 244, 248, 0.58);
  position: relative;
  isolation: isolate;
  width: 100%;
  height: 100svh;
  min-height: 680px;
  overflow: hidden;
  background: #0d0718;
  color: var(--lodestar-ink);
  cursor: none;
  font-family: "Red Hat Display", ui-sans-serif, system-ui, sans-serif;
}

.hero-lodestar *,
.hero-lodestar *::before,
.hero-lodestar *::after {
  box-sizing: border-box;
}

.hero-lodestar button,
.hero-lodestar a {
  color: inherit;
  font: inherit;
}

.hero-lodestar a {
  text-decoration: none;
}

.hero-lodestar__aurora {
  position: absolute;
  inset: 0;
  z-index: -3;
  background: #0d0718;
}

.hero-lodestar__aurora::after {
  position: absolute;
  inset: 0;
  background: radial-gradient(110% 100% at 50% 44%, transparent 48%, rgba(4, 1, 10, 0.48) 100%);
  content: "";
}

.hero-lodestar__canvas {
  position: absolute;
  inset: 0;
  z-index: -2;
  display: block;
  width: 100%;
  height: 100%;
  opacity: 0;
  animation: hero-lodestar-canvas-in 0.8s 1.34s ease forwards;
}

.hero-lodestar__frame {
  position: absolute;
  inset: 16px;
  z-index: 8;
  border: 1px solid rgba(255, 255, 255, 0.1);
  pointer-events: none;
}

.hero-lodestar__corner {
  position: absolute;
  width: 18px;
  height: 18px;
  border-color: rgba(226, 214, 255, 0.66);
  border-style: solid;
}

.hero-lodestar__corner--tl {
  top: -1px;
  left: -1px;
  border-width: 2px 0 0 2px;
}

.hero-lodestar__corner--tr {
  top: -1px;
  right: -1px;
  border-width: 2px 2px 0 0;
}

.hero-lodestar__corner--bl {
  bottom: -1px;
  left: -1px;
  border-width: 0 0 2px 2px;
}

.hero-lodestar__corner--br {
  right: -1px;
  bottom: -1px;
  border-width: 0 2px 2px 0;
}

.hero-lodestar__header {
  position: absolute;
  top: 0;
  right: 32px;
  left: 32px;
  z-index: 12;
  display: flex;
  height: 80px;
  align-items: center;
  justify-content: space-between;
  animation: hero-lodestar-content-in 0.8s 1.28s both;
}

.hero-lodestar__brand {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.03em;
}

.hero-lodestar__header-actions,
.hero-lodestar__locales {
  display: flex;
  align-items: center;
}

.hero-lodestar__header-actions {
  gap: 22px;
}

.hero-lodestar__locales {
  gap: 5px;
  color: rgba(245, 244, 248, 0.34);
  font-size: 14px;
  line-height: 1;
}

.hero-lodestar__locales button,
.hero-lodestar__menu-toggle {
  padding: 0;
  border: 0;
  background: transparent;
  cursor: none;
}

.hero-lodestar__locales button {
  color: rgba(245, 244, 248, 0.34);
  transition: color 180ms ease;
}

.hero-lodestar__locales button:hover,
.hero-lodestar__locales button.is-active {
  color: var(--lodestar-ink);
}

.hero-lodestar__menu-toggle {
  position: relative;
  z-index: 14;
  width: 24px;
  height: 24px;
}

.hero-lodestar__menu-toggle span {
  position: absolute;
  right: 0;
  width: 23px;
  height: 1.5px;
  background: var(--lodestar-ink);
  transition: top 420ms cubic-bezier(0.16, 1, 0.3, 1), transform 420ms cubic-bezier(0.16, 1, 0.3, 1);
}

.hero-lodestar__menu-toggle span:first-child {
  top: 8px;
}

.hero-lodestar__menu-toggle span:last-child {
  top: 15px;
}

.hero-lodestar__menu-toggle.is-open span:first-child {
  top: 11px;
  transform: rotate(12deg);
}

.hero-lodestar__menu-toggle.is-open span:last-child {
  top: 11px;
  transform: rotate(-12deg);
}

.hero-lodestar__menu {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 11;
  display: flex;
  width: 156px;
  padding: 46px 18px 18px;
  flex-direction: column;
  align-items: flex-end;
  background: rgba(36, 20, 68, 0.42);
  backdrop-filter: blur(18px);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-12px) scaleY(0.84);
  transform-origin: top;
  transition: opacity 360ms ease, transform 560ms cubic-bezier(0.16, 1, 0.3, 1);
}

.hero-lodestar__menu.is-open {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0) scaleY(1);
}

.hero-lodestar__menu a {
  position: relative;
  padding: 2px 0;
  color: rgba(245, 244, 248, 0.74);
  font-size: 14px;
  line-height: 1.35;
  cursor: none;
  transition: color 180ms ease;
}

.hero-lodestar__menu a::after {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 1px;
  background: currentColor;
  content: "";
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 320ms cubic-bezier(0.16, 1, 0.3, 1);
}

.hero-lodestar__menu a:hover {
  color: #fff;
}

.hero-lodestar__menu a:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.hero-lodestar__intro-copy {
  position: absolute;
  top: 120px;
  left: clamp(58px, 6.6667vw, 96px);
  z-index: 4;
  width: 480px;
  max-width: calc(100vw - 116px);
  animation: hero-lodestar-content-in 0.9s 1.22s both;
}

.hero-lodestar__eyebrow {
  margin: 0 0 12px;
  font-size: 16px;
  line-height: 1.5;
}

.hero-lodestar__intro-copy h1 {
  margin: 0;
  font-family: "Instrument Serif", Georgia, serif;
  font-size: 64px;
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.018em;
  line-height: 0.9;
}

.hero-lodestar__title-line {
  display: block;
  color: var(--lodestar-muted);
}

.hero-lodestar__title-line--bright {
  color: var(--lodestar-ink);
}

.hero-lodestar__actions {
  position: absolute;
  bottom: 80px;
  left: clamp(58px, 6.6667vw, 96px);
  z-index: 5;
  display: flex;
  gap: 16px;
  animation: hero-lodestar-content-in 0.9s 1.36s both;
}

.hero-lodestar__actions a {
  display: inline-flex;
  min-width: 148px;
  height: 48px;
  padding: 0 23px;
  border: 1px solid rgba(245, 244, 248, 0.2);
  border-radius: 999px;
  align-items: center;
  justify-content: center;
  background: rgba(245, 244, 248, 0.02);
  font-size: 16px;
  cursor: none;
  transition: border-color 220ms ease, background-color 220ms ease, transform 220ms ease;
}

.hero-lodestar__actions a:hover {
  border-color: rgba(229, 212, 255, 0.62);
  background: rgba(122, 76, 211, 0.18);
  transform: translateY(-2px);
}

.hero-lodestar__description {
  position: absolute;
  right: clamp(58px, 6.6667vw, 96px);
  bottom: 80px;
  z-index: 4;
  width: 360px;
  margin: 0;
  font-size: 16px;
  line-height: 1.5;
  animation: hero-lodestar-content-in 0.9s 1.45s both;
}

.hero-lodestar__cursor {
  position: absolute;
  top: -12px;
  left: -12px;
  z-index: 30;
  width: 24px;
  height: 24px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 160ms ease;
  will-change: transform;
}

.hero-lodestar__cursor::before,
.hero-lodestar__cursor::after {
  position: absolute;
  top: 50%;
  left: 50%;
  background: rgba(255, 255, 255, 0.96);
  content: "";
  transform: translate(-50%, -50%);
}

.hero-lodestar__cursor::before {
  width: 13px;
  height: 1.5px;
}

.hero-lodestar__cursor::after {
  width: 1.5px;
  height: 13px;
}

.hero-lodestar__cursor span {
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  box-shadow: 0 0 18px rgba(183, 134, 255, 0.75);
}

.hero-lodestar__loader {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  background: #24173e;
  animation: hero-lodestar-loader-out 0.7s 1.05s cubic-bezier(0.76, 0, 0.24, 1) forwards;
}

.hero-lodestar__loader p {
  margin: 0;
  color: rgba(245, 244, 248, 0.6);
  font-family: "Instrument Serif", Georgia, serif;
  font-size: clamp(34px, 3vw, 52px);
  animation: hero-lodestar-loader-copy 1.1s ease both;
}

.hero-lodestar :focus-visible {
  outline: 2px solid #c9a7ff;
  outline-offset: 4px;
}

@keyframes hero-lodestar-aurora {
  from { transform: scale(1) translate3d(0, 0, 0); }
  to { transform: scale(1.06) translate3d(1.5%, -1%, 0); }
}

@keyframes hero-lodestar-canvas-in {
  /* The reference composites its entire WebGL layer at 60% opacity. */
  to { opacity: 0.6; }
}

@keyframes hero-lodestar-content-in {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes hero-lodestar-loader-copy {
  0% { opacity: 0; transform: translateY(16px); }
  30%, 68% { opacity: 0.64; transform: translateY(0); }
  100% { opacity: 0; transform: translateY(-8px); }
}

@keyframes hero-lodestar-loader-out {
  0%, 28% { opacity: 1; }
  100% { opacity: 0; visibility: hidden; }
}

@media (max-width: 767px) {
  .hero-lodestar {
    min-height: 620px;
  }

  .hero-lodestar__frame {
    inset: 10px;
  }

  .hero-lodestar__header {
    top: 0;
    right: 24px;
    left: 24px;
    height: 68px;
  }

  .hero-lodestar__brand {
    font-size: 15px;
  }

  .hero-lodestar__header-actions {
    gap: 13px;
  }

  .hero-lodestar__locales {
    font-size: 12px;
  }

  .hero-lodestar__menu {
    top: 10px;
    right: 10px;
    width: 148px;
  }

  .hero-lodestar__intro-copy {
    top: 112px;
    left: 30px;
    width: calc(100% - 60px);
    max-width: none;
  }

  .hero-lodestar__eyebrow {
    margin-bottom: 8px;
    font-size: 12px;
  }

  .hero-lodestar__intro-copy h1 {
    max-width: 340px;
    font-size: clamp(44px, 13vw, 58px);
    line-height: 0.92;
  }

  .hero-lodestar__description {
    right: 30px;
    bottom: 106px;
    left: 30px;
    width: auto;
    max-width: 390px;
    font-size: 13px;
    line-height: 1.45;
  }

  .hero-lodestar__actions {
    right: 30px;
    bottom: 30px;
    left: 30px;
    gap: 10px;
  }

  .hero-lodestar__actions a {
    min-width: 0;
    height: 44px;
    padding: 0 18px;
    flex: 1;
    font-size: 13px;
  }
}

@media (pointer: coarse) {
  .hero-lodestar {
    cursor: auto;
  }

  .hero-lodestar__locales button,
  .hero-lodestar__menu-toggle,
  .hero-lodestar__menu a,
  .hero-lodestar__actions a {
    cursor: pointer;
  }

  .hero-lodestar__cursor {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-lodestar__aurora,
  .hero-lodestar__header,
  .hero-lodestar__intro-copy,
  .hero-lodestar__actions,
  .hero-lodestar__description,
  .hero-lodestar__loader,
  .hero-lodestar__loader p {
    animation: none;
  }

  .hero-lodestar__canvas,
  .hero-lodestar__header,
  .hero-lodestar__intro-copy,
  .hero-lodestar__actions,
  .hero-lodestar__description {
    opacity: 1;
  }

  .hero-lodestar__loader {
    display: none;
  }

  .hero-lodestar__canvas {
    animation: none;
    opacity: 0.6;
  }
}

import { useEffect, useRef } from "react"
import * as THREE from "three"
import { MeshSurfaceSampler } from "three/addons/math/MeshSurfaceSampler.js"

import {
  BACKGROUND_FRAGMENT, BACKGROUND_VERTEX, COMPOSITE_FRAGMENT,
  DUST_FRAGMENT, DUST_VERTEX, SCREEN_VERTEX, STAR_FRAGMENT,
  STAR_INDICES, STAR_VERTEX, STAR_VERTICES, TRAIL_FRAGMENT,
} from "./lodestar-source"

// Parameters from the source's graphics profile and particle configuration.
// The hero is a mesh-sampled extruded star, NOT a rotating volumetric point cloud.
const SOURCE = {
  cameraZ: 800,
  sizeFill: 0.68,
  shapeScale: 0.48 / 2.55,
  zRange: 0.12,
  sizeRef: 5600,
  tilt: 0.58,
  rotationSpeed: 9,
  cursorRadius: 78,
  cursorForce: 34,
  cursorReturn: 5.2,
  color: "#58467b",
}

function seededRandom(seed: number) {
  return () => {
    let n = (seed += 0x6d2b79f5)
    n = Math.imul(n ^ (n >>> 15), n | 1)
    n ^= n + Math.imul(n ^ (n >>> 7), n | 61)
    return ((n ^ (n >>> 14)) >>> 0) / 4294967296
  }
}

export function ParticleLodestar() {
  const canvasRef = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = canvasRef.current
    const section = canvas?.closest<HTMLElement>(".hero-lodestar")
    if (!canvas || !section) return
    const cursor = section.querySelector<HTMLElement>(".hero-lodestar__cursor")
    const motionQuery = window.matchMedia("(prefers-reduced-motion: reduce)")
    const coarse = window.matchMedia("(hover: none) and (pointer: coarse)").matches
    const cores = navigator.hardwareConcurrency || 8
    const memory = (navigator as Navigator & { deviceMemory?: number }).deviceMemory
    const low = motionQuery.matches
    const medium = !low && (coarse || (memory !== undefined && memory <= 4) || (cores <= 4 && window.devicePixelRatio >= 2))
    const count = low ? 1800 : medium ? 2800 : 4000
    const dustCount = low ? 3000 : medium ? 6000 : 10000
    const twinkleFraction = low ? 0 : medium ? 0.2 : 0.4
    const twinkleIntensity = low ? 0 : medium ? 1.8 : 3.5
    const pixelRatio = Math.min(window.devicePixelRatio || 1, low ? 1 : medium ? 1.5 : 2)
    const random = seededRandom(481516)
    let renderer: THREE.WebGLRenderer
    try {
      renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: false, powerPreference: "high-performance" })
    } catch {
      section.dataset.webgl = "unavailable"
      return
    }
    renderer.setPixelRatio(pixelRatio)
    renderer.outputColorSpace = THREE.SRGBColorSpace
    renderer.toneMapping = THREE.NoToneMapping
    renderer.autoClear = false

    const starScene = new THREE.Scene()
    const starGroup = new THREE.Group()
    starScene.add(starGroup)
    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 1600)
    camera.position.z = SOURCE.cameraZ
    const sourceGeometry = new THREE.BufferGeometry()
    sourceGeometry.setAttribute("position", new THREE.BufferAttribute(STAR_VERTICES.slice(), 3))
    sourceGeometry.setIndex(new THREE.BufferAttribute(STAR_INDICES.slice(), 1))
    // three@0.170 implements this method; its matching DefinitelyTyped package omits it.
    const samplingMaterial = new THREE.MeshBasicMaterial()
    const samplingMesh = new THREE.Mesh(sourceGeometry, samplingMaterial)
    const sampler = new MeshSurfaceSampler(samplingMesh) as MeshSurfaceSampler & {
      setRandomGenerator(generator: () => number): MeshSurfaceSampler
    }
    sampler.setRandomGenerator(random).build()
    samplingMaterial.dispose()
    const point = new THREE.Vector3()
    const positions = new Float32Array(count * 3)
    const colors = new Float32Array(count * 3)
    const sizes = new Float32Array(count)
    const brightness = new Float32Array(count)
    const opacity = new Float32Array(count)
    const baseColor = new THREE.Color(SOURCE.color)
    const particles = Array.from({ length: count }, () => {
      sampler.sample(point)
      return {
        x: point.x * SOURCE.shapeScale,
        y: point.y * SOURCE.shapeScale,
        z: point.z * SOURCE.shapeScale,
        spawnX: 0, spawnY: 0, spawnZ: 0, offX: 0, offY: 0,
        dissolveDelay: 0,
        baseSize: 0.1 + (10 - 0.1) * random() * 0.32,
        phase: random() * Math.PI * 2,
        noisePhase: random() * Math.PI * 2,
        twinkle: 0.35 + 0.65 * random(),
        hasTwinkle: false,
        twinklePhase: random() * Math.PI * 2,
        twinkleSpeed: 0.85 + 2.2 * random(),
      }
    })
    // Exact percentage, shuffled independently of sample positions.
    const order = particles.map((_, i) => i)
    for (let i = order.length - 1; i > 0; i--) {
      const j = Math.floor(random() * (i + 1))
      ;[order[i], order[j]] = [order[j], order[i]]
    }
    for (let i = 0; i < Math.round(count * twinkleFraction); i++) particles[order[i]].hasTwinkle = true
    const maxDistance = Math.max(...particles.map(p => Math.hypot(p.x, p.y, p.z)))
    particles.forEach((p, i) => {
      p.dissolveDelay = (1 - Math.hypot(p.x, p.y, p.z) / maxDistance) * 0.65
      baseColor.toArray(colors, i * 3)
    })
